function modal(title,subtitle,body,footer='',wide=false){closeModal();const last=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${e(title)}</h2><p>${e(subtitle)}</p></div><button id="modal-close" class="icon-btn" aria-label="${tf('close')}">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('#modal-close').onclick=closeModal;$('#modal-root').addEventListener('keydown',trapFocus);const escape=ev=>{if(ev.key==='Escape')closeModal();};document.addEventListener('keydown',escape);currentModalClose=()=>{document.removeEventListener('keydown',escape);$('#modal-root').removeEventListener('keydown',trapFocus);last?.focus();};setTimeout(()=>$('#modal-root input, #modal-root textarea, #modal-root select, #modal-close')?.focus(),0);return $('#modal-root');}
function trapFocus(event){if(event.key!=='Tab')return;const elements=$$('button:not([disabled]),a,input:not([disabled]),select,textarea,[tabindex="0"]',$('#modal-root')).filter(x=>x.offsetParent!==null);const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
