function connectionEditor(connection=null){modal(t(connection?'editConnection':'newConnection'),t('connectionEditorDesc'),`<div class="fields">${field('name','connection-name',connection?.name||'')}${selectField('connectorType','connection-type',me.connectors.map(x=>x.type),connection?.type||'REST')}</div><div id="db-profile" class="field" hidden><label for="db-vendor">${tf('databaseProfile')}</label><select id="db-vendor">${Object.keys(dbProfiles).map(k=>`<option>${k}</option>`).join('')}</select><small>${tf('driverNote')}</small></div>${textarea('connectionConfig','connection-config',pretty(connection?.config||connectionTemplate('REST')),'advancedSaved')}<div class="notice">${tf('secretWriteOnly')}</div><div class="fields">${field('username','secret-username','','text')}${field('password','secret-password','','password')}${field('bearerToken','secret-token','','password')}${field('apiKey','secret-apiKey','','password')}</div>${connection?.configuredSecrets.length?`<p class="small-text muted">${tf('configuredSecrets')}: ${e(connection.configuredSecrets.join(', '))}</p>`:''}<div id="modal-error" class="error-message" role="alert"></div>`,`${connection?btn('delete','delete-connection','trash'): '<span></span>'}${btn('saveConnection','save-connection','check',true)}`);
 const type=$('#connection-type');if(connection)type.disabled=true;const profile=()=>{$('#db-profile').hidden=type.value!=='JDBC';};profile();type.onchange=()=>{$('#connection-config').value=pretty(connectionTemplate(type.value));profile();};$('#db-vendor').onchange=ev=>{$('#connection-config').value=pretty(dbProfiles[ev.target.value]);};$('#save-connection').onclick=async()=>{try{const secrets={};for(const name of ['username','password','token','apiKey']){const value=$('#secret-'+name).value;if(value)secrets[name]=value;}const body={name:$('#connection-name').value,type:type.value,config:JSON.parse($('#connection-config').value),secrets,...(connection?{version:connection.version}:{})};await api('/api/connections'+(connection?'/'+connection.id:''),{method:connection?'PUT':'POST',body});closeModal();toast(t('saved'));await renderPage();}catch(err){$('#modal-error').textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);}};$('#delete-connection')?.addEventListener('click',async()=>{if(!confirm(t('confirmDelete')))return;try{await api('/api/connections/'+connection.id,{method:'DELETE',headers:{'If-Match':String(connection.version)}});closeModal();await renderPage();}catch(err){$('#modal-error').textContent=errorText(err);}});}
async function discover(connection){modal(t('inspectConnection'),connection.name,`<div class="notice">${tf('discoveryNotice')}</div>${connection.type==='JDBC'?field('schemaOptional','discover-schema'):''}${connection.type==='SOAP'?textarea('wsdlDocument','wsdl-content','','wsdlNotice'):''}<div class="row">${btn('discover','run-discovery','database',true)}${['JDBC','LOCAL'].includes(connection.type)?btn('generateCrud','generate-crud','layers'):''}</div><div class="spacer" id="discovery-result"></div><div id="modal-error" class="error-message" role="alert"></div>`,'',true);$('#run-discovery').onclick=async()=>{try{const body={};if($('#discover-schema')?.value)body.schema=$('#discover-schema').value;if($('#wsdl-content')?.value)body.wsdl=$('#wsdl-content').value;const result=await api('/api/connections/'+connection.id+'/discover',{method:'POST',body});$('#discovery-result').innerHTML=`<pre class="result-box">${e(pretty(result))}</pre>`;}catch(err){$('#modal-error').textContent=errorText(err);}};$('#generate-crud')?.addEventListener('click',async()=>{const table=prompt(t('tablePrompt'),connection.type==='LOCAL'?'records':'CUSTOMERS');if(!table)return;try{const result=await api('/api/connections/'+connection.id+'/generate-crud',{method:'POST',body:{table,schema:$('#discover-schema')?.value||''}});closeModal();toast(num(result.length)+' '+t('providersCreated'));await navigate('providers');}catch(err){$('#modal-error').textContent=errorText(err);}});}
async function providerPage(target){[providers,connections]=await Promise.all([api('/api/providers'),api('/api/connections')]);target.innerHTML=head('providersTitle','providersDesc',btn('newProvider','new-provider','plus',true))+`<div class="toolbar">${searchControl()}${btn('importOpenApi','import-openapi','download')}</div><div class="panel" id="provider-list"></div>`;renderProviderList();$('#list-search').oninput=ev=>{searchText=ev.target.value;renderProviderList();};$('#new-provider').onclick=()=>providerEditor();$('#import-openapi').onclick=importOpenApi;}
function renderProviderList(){const filtered=providers.filter(p=>pretty(p).toLowerCase().includes(searchText.toLowerCase()));$('#provider-list').innerHTML=filtered.length?`<div class="table-wrap"><table><thead><tr><th>${tf('provider')}</th><th>${tf('connection')}</th><th>${tf('operation')}</th><th>${tf('version')}</th><th class="right">${tf('actions')}</th></tr></thead><tbody>${filtered.map(p=>{const c=connections.find(x=>x.id===p.connectionId);return `<tr><td><div class="row-title">${e(p.name)}</div><div class="sub mono">${e(p.slug)}</div></td><td><span class="badge">${e(c?.type||'')}</span><div class="sub">${e(c?.name||p.connectionId)}</div></td><td>${badge(p.operation)}</td><td><span class="badge">v${num(p.version)}</span></td><td><div class="table-actions"><button class="button small" data-run="${e(p.id)}">${icon('play')}${tf('test')}</button><button class="button small" data-edit-provider="${e(p.id)}">${icon('edit')}${tf('edit')}</button><button class="button small primary" data-publish="${e(p.id)}">${icon('globe')}${tf('publish')}</button></div></td></tr>`;}).join('')}</tbody></table></div>`:empty('createFirstProvider');$$('[data-run]').forEach(b=>b.onclick=()=>executionDialog(providers.find(p=>p.id===b.dataset.run)));$$('[data-edit-provider]').forEach(b=>b.onclick=()=>providerEditor(providers.find(p=>p.id===b.dataset.editProvider)));$$('[data-publish]').forEach(b=>b.onclick=async()=>{const p=providers.find(p=>p.id===b.dataset.publish);if(!confirm(t('confirmPublish')))return;try{const pub=await api('/api/providers/'+p.id+'/publish',{method:'POST',body:{version:p.version}});toast(t('published')+' '+pub.path);await navigate('services');}catch(err){toast(errorText(err));}});}
function defaultProvider(connection,operation='READ'){switch(connection?.type){case 'LOCAL':return {collection:'customers',body:{name:'${name}'}};case 'JDBC':if(['QUERY','EXECUTE'].includes(operation))return {sql:'SELECT * FROM CUSTOMERS WHERE ID = :id'};if(['PROCEDURE','FUNCTION'].includes(operation))return {routine:'public.example',routineParameters:[{name:'id',mode:'IN',type:'INTEGER'}],returnType:'VARCHAR'};return {table:'CUSTOMERS',schema:'PUBLIC',keyColumn:'ID',keyParameter:'id',columns:[],bindings:{NAME:'name'}};case 'SOAP':return {path:'/soap',soapVersion:'1.1',soapAction:'urn:demo/Add',envelope:'<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" xmlns:d="urn:demo"><s:Body><d:Add><d:a>${a}</d:a><d:b>${b}</d:b></d:Add></s:Body></s:Envelope>'};case 'GRAPHQL':return {path:'/graphql',document:'query WorkOrders { workOrders { id status priority } }',variables:{}};case 'REDIS':return {ttlSeconds:0};case 'MONGODB':return {collection:'customers',filter:{},body:{name:'${name}'}};default:return {method:operation==='READ'?'GET':operation==='DELETE'?'DELETE':operation==='UPDATE'?'PATCH':'POST',path:connection?.type==='ODATA'?'/odata/Products':'/customers',responseType:'JSON',...(operation==='READ'?{}:{body:{name:'${name}'}})};}}
function parameterRow(p={},mapping=false){if(mapping)return `<tr><td><input class="name-field" data-col="name" aria-label="${tf('name')}" value="${e(p.name||'')}"></td><td><input class="mono" data-col="pointer" aria-label="${tf('jsonPointer')}" value="${e(p.pointer||'')}"></td><td><select data-col="type" aria-label="${tf('dataType')}">${['JSON','STRING','INTEGER','DECIMAL','BOOLEAN','DATE','DATETIME'].map(x=>`<option ${x===(p.type||'JSON')?'selected':''}>${x}</option>`).join('')}</select></td><td><input type="checkbox" data-col="required" aria-label="${tf('required')}" ${p.required?'checked':''}></td><td><button class="icon-btn remove-row" aria-label="${tf('remove')}">${icon('trash')}</button></td></tr>`;
 return `<tr><td><input class="name-field" data-col="name" aria-label="${tf('name')}" value="${e(p.name||'')}"></td><td><select data-col="type" aria-label="${tf('dataType')}">${['STRING','INTEGER','DECIMAL','BOOLEAN','JSON','DATE','DATETIME'].map(x=>`<option ${x===(p.type||'STRING')?'selected':''}>${x}</option>`).join('')}</select></td><td><select data-col="source" aria-label="${tf('source')}">${['INPUT','CONSTANT','SYSTEM','CONFIG','SECRET'].map(x=>`<option value="${x}" ${x===(p.source||'INPUT')?'selected':''}>${tf('source.'+x)}</option>`).join('')}</select></td><td><select data-col="location" aria-label="${tf('location')}">${['BODY','QUERY','PATH','HEADER'].map(x=>`<option ${x===(p.location||'BODY')?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-col="value" class="value-field" aria-label="${tf('valueReference')}" value="${e(p.value===undefined?'':typeof p.value==='object'?JSON.stringify(p.value):p.value)}"></td><td><input type="checkbox" data-col="required" aria-label="${tf('required')}" ${p.required?'checked':''}></td><td><button class="icon-btn remove-row" aria-label="${tf('remove')}">${icon('trash')}</button></td></tr>`;}
function bindRemoveRows(){ $$('.remove-row').forEach(b=>b.onclick=()=>b.closest('tr').remove());}
function readRows(id,mapping=false){return $$('tbody tr',$(id)).map(row=>{const obj={};$$('[data-col]',row).forEach(el=>{if(el.type==='checkbox')obj[el.dataset.col]=el.checked;else if(el.dataset.col==='value'){if(el.value!==''){obj.value=el.value;}}else obj[el.dataset.col]=el.value;});if(!mapping&&obj.source==='CONSTANT'&&obj.type==='JSON'&&obj.value!==undefined)obj.value=JSON.parse(obj.value);return obj;});}
async function providerEditor(provider=null){if(!connections.length)connections=await api('/api/connections');if(!connections.length){toast(t('needConnection'));return;}const conn=connections.find(c=>c.id===provider?.connectionId)||connections[0];const p=provider||{name:'',slug:'',connectionId:conn.id,operation:'READ',parameters:[],outputMappings:[],fieldsRoot:'/data',config:defaultProvider(conn),timeoutMs:10000,maxAttempts:1,rateLimit:120};
 modal(t(provider?'editProvider':'newProvider'),t('providerEditorDesc'),`<div class="tabs" role="tablist">${['general','parameters','request','output','resilience'].map((name,i)=>`<button role="tab" aria-selected="${i===0}" data-tab="${name}" class="${i===0?'active':''}">${tf('tab.'+name)}</button>`).join('')}</div><div class="tab-content" data-panel="general"><div class="fields">${field('name','provider-name',p.name)}${field('serviceSlug','provider-slug',p.slug,'text','slugHelp')}${selectField('connection','provider-connection',connections.map(c=>[c.id,c.name+' / '+c.type]),p.connectionId)}${selectField('operation','provider-operation',me.connectors.find(c=>c.type===conn.type).operations,p.operation)}</div><div class="field"><label for="provider-description">${tf('description')}</label><textarea id="provider-description">${e(p.description||'')}</textarea></div><div class="notice">${tf('publishedSnapshotNotice')}</div></div><div class="tab-content" data-panel="parameters" hidden><div class="notice">${tf('parameterSourcesHelp')}</div><div class="table-wrap"><table class="param-table" id="parameter-table"><thead><tr>${['name','dataType','source','location','valueReference','required','actions'].map(k=>`<th>${tf(k)}</th>`).join('')}</tr></thead><tbody>${p.parameters.map(x=>parameterRow(x)).join('')}</tbody></table></div><div class="row spacer">${btn('addParameter','add-parameter')}${btn('detectBindings','detect-bindings','code')}</div></div><div class="tab-content" data-panel="request" hidden><div id="guided-request"></div>${textarea('operationConfig','provider-config',pretty(p.config),'advancedSaved',true)}</div><div class="tab-content" data-panel="output" hidden>${field('fieldsRoot','provider-root',p.fieldsRoot??'/data','text','fieldsRootHelp')}<div class="table-wrap"><table class="param-table" id="mapping-table"><thead><tr>${['name','jsonPointer','dataType','required','actions'].map(k=>`<th>${tf(k)}</th>`).join('')}</tr></thead><tbody>${(p.outputMappings||[]).map(x=>parameterRow(x,true)).join('')}</tbody></table></div><div class="spacer">${btn('addMapping','add-mapping')}</div><div class="notice spacer">${tf('mappingHelp')}</div></div><div class="tab-content" data-panel="resilience" hidden><div class="fields">${field('timeoutMs','provider-timeout',p.timeoutMs||10000,'number')}${field('maxAttempts','provider-attempts',p.maxAttempts||1,'number','safeReadsOnly')}${field('rateLimit','provider-rate',p.rateLimit||120,'number','rateLimitHelp')}</div><div class="notice warning">${tf('idempotencyNotice')}</div></div><div id="modal-error" class="error-message" role="alert"></div>`,`${provider?btn('delete','delete-provider','trash'):'<span class="small-text muted">'+tf('draftOnly')+'</span>'}${btn('saveProvider','save-provider','check',true)}`,true);
 $$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b?'true':'false');});$$('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==b.dataset.tab);});
 bindRemoveRows();$('#add-parameter').onclick=()=>{$('#parameter-table tbody').insertAdjacentHTML('beforeend',parameterRow());bindRemoveRows();};$('#add-mapping').onclick=()=>{$('#mapping-table tbody').insertAdjacentHTML('beforeend',parameterRow({},true));bindRemoveRows();};
 $('#detect-bindings').onclick=()=>{const existing=new Set(readRows('#parameter-table').map(x=>x.name));const config=$('#provider-config').value;const names=new Set([...config.matchAll(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g)].map(x=>x[1]));try{const sql=JSON.parse(config).sql||'';for(const match of sql.matchAll(/(?<!:):([A-Za-z_][A-Za-z0-9_]*)/g))names.add(match[1]);}catch{}for(const name of names)if(!existing.has(name))$('#parameter-table tbody').insertAdjacentHTML('beforeend',parameterRow({name,required:true}));bindRemoveRows();};
 const changed=()=>{const selected=connections.find(x=>x.id===$('#provider-connection').value);const operation=$('#provider-operation');const ops=me.connectors.find(x=>x.type===selected.type).operations;operation.innerHTML=ops.map(x=>`<option>${x}</option>`).join('');operation.value=ops.includes('READ')?'READ':ops[0];$('#provider-config').value=pretty(defaultProvider(selected,operation.value));guidedRequest(selected,operation.value);};$('#provider-connection').onchange=changed;$('#provider-operation').onchange=()=>{const selected=connections.find(x=>x.id===$('#provider-connection').value);$('#provider-config').value=pretty(defaultProvider(selected,$('#provider-operation').value));guidedRequest(selected,$('#provider-operation').value);};guidedRequest(conn,p.operation);
 $('#save-provider').onclick=async()=>{try{const body={name:$('#provider-name').value,slug:$('#provider-slug').value,connectionId:$('#provider-connection').value,operation:$('#provider-operation').value,description:$('#provider-description').value,parameters:readRows('#parameter-table'),outputMappings:readRows('#mapping-table',true),fieldsRoot:$('#provider-root').value,config:JSON.parse($('#provider-config').value),timeoutMs:Number($('#provider-timeout').value),maxAttempts:Number($('#provider-attempts').value),rateLimit:Number($('#provider-rate').value),...(provider?{version:provider.version}:{})};await api('/api/providers'+(provider?'/'+provider.id:''),{method:provider?'PUT':'POST',body});closeModal();toast(t('saved'));await renderPage();}catch(err){$('#modal-error').textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);}};$('#delete-provider')?.addEventListener('click',async()=>{if(!confirm(t('confirmDelete')))return;try{await api('/api/providers/'+provider.id,{method:'DELETE',headers:{'If-Match':String(provider.version)}});closeModal();await renderPage();}catch(err){$('#modal-error').textContent=errorText(err);}});
}
function guidedRequest(connection,operation){let cfg={};try{cfg=JSON.parse($('#provider-config').value);}catch{}const target=$('#guided-request');let keys=[];if(['REST','ODATA'].includes(connection.type)){keys=[['method','httpMethod','select',['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS']],['path','relativePath']];}else if(connection.type==='SOAP')keys=[['path','relativePath'],['soapAction','soapAction'],['soapVersion','soapVersion','select',['1.1','1.2']]];else if(connection.type==='GRAPHQL')keys=[['path','relativePath']];else if(connection.type==='JDBC'&&['READ','CREATE','UPDATE','DELETE'].includes(operation))keys=[['table','table'],['schema','schema'],['keyColumn','keyColumn']];else if(connection.type==='LOCAL'||connection.type==='MONGODB')keys=[['collection','collection']];target.innerHTML=keys.length?`<div class="fields">${keys.map(([key,label,type,options])=>type==='select'?selectField(label,'guided-'+key,options,cfg[key]||options[0]):field(label,'guided-'+key,cfg[key]||'')).join('')}</div>`:'';for(const [key]of keys)$('#guided-'+key).onchange=ev=>{try{const config=JSON.parse($('#provider-config').value);config[key]=ev.target.value;$('#provider-config').value=pretty(config);}catch{toast(t('invalidJson'));}};}
function sampleInput(p){const input={};for(const d of p.parameters||[]){if((d.source||'INPUT')!=='INPUT')continue;if(d.value!==undefined){input[d.name]=d.value;continue;}if(!d.required)continue;input[d.name]=d.type==='INTEGER'||d.type==='DECIMAL'?1:d.type==='BOOLEAN'?true:d.type==='JSON'?{}:d.type==='DATE'?'2026-10-10':d.type==='DATETIME'?'2026-10-10T12:00:00Z':d.name==='name'?'Demo customer':d.name==='id'?'demo-1':'example';}return input;}
function executionDialog(provider,path=null){const destination=path||'/api/providers/'+provider.id+'/execute';modal(t('executeProvider'),provider.name,`<div class="notice ${provider.operation!=='READ'?'warning':''}">${tf(path?'publishedExecutionNotice':'draftExecutionNotice')}</div><div class="test-columns"><section>${textarea('inputJson','execution-input',pretty(sampleInput(provider)),'inputOnlyHelp',true)}<div class="fields">${field('pageIndex','execution-page',0,'number')}${field('pageSize','execution-size',50,'number')}</div>${textarea('pageFilters','execution-filters','[]','filtersHelp')}<div class="field"><label for="execution-key">${tf('idempotencyKey')}</label><div class="row"><input class="mono" id="execution-key" value="${newIdempotencyKey()}"><button id="new-key" class="button small" title="${tf('newKey')}">${icon('refresh')}</button></div></div><div class="check-field"><input type="checkbox" id="execution-async"><label for="execution-async">${tf('runAsync')}</label></div><div class="row">${btn('runProvider','run-provider','play',true)}<button id="copy-curl" class="button">${icon('copy')}cURL</button></div></section><section><div class="section-title"><h3>${tf('response')}</h3><span class="badge blue" id="execution-state">${tf('ready')}</span></div><pre class="result-box" id="execution-result">${tf('responsePlaceholder')}</pre><div id="result-actions" class="row spacer"></div><div class="notice spacer">${tf('reuseKeyNotice')}</div></section></div><div id="modal-error" class="error-message" role="alert"></div>`,'',true);
 // Capture this dialog's elements before awaiting a response. A closed/replaced
 // dialog must not receive late results or modify a newer dialog with the same IDs.
 const dialog=$('#modal-root .modal');
 const find=selector=>$(selector,dialog);
 const button=find('#run-provider');
 const state=find('#execution-state');
 const resultBox=find('#execution-result');
 const actions=find('#result-actions');
 const errorBox=find('#modal-error');
 const keyInput=find('#execution-key');
 find('#new-key').onclick=()=>{keyInput.value=newIdempotencyKey();};
 const request=()=>({
   input:JSON.parse(find('#execution-input').value),
   page:{index:Number(find('#execution-page').value),size:Number(find('#execution-size').value),filters:JSON.parse(find('#execution-filters').value)},
   async:find('#execution-async').checked
 });
 button.onclick=async()=>{
   if(button.disabled||!dialog.isConnected)return;
   button.disabled=true;
   state.textContent=t('running');
   errorBox.textContent='';
   try{
     const result=await api(destination,{method:'POST',headers:{'Idempotency-Key':keyInput.value},body:request()});
     // Closing the UI does not cancel or retry an operation at the destination.
     if(!dialog.isConnected)return;
     resultBox.textContent=pretty(result);
     state.textContent=t('status.'+(result.status||'SUCCEEDED'));
     actions.innerHTML='';
     if(result.data?.contentBase64){
       actions.innerHTML=btn('downloadFile','download-result','download');
       find('#download-result').onclick=()=>{
         const raw=atob(result.data.contentBase64);
         download(new Uint8Array([...raw].map(c=>c.charCodeAt(0))),result.data.filename||'download.bin',result.data.contentType||'application/octet-stream');
       };
     }
     if(result.id&&result.status==='QUEUED'){
       actions.innerHTML=btn('viewJobs','view-jobs','clock');
       find('#view-jobs').onclick=()=>{closeModal();navigate('jobs');};
     }
   }catch(err){
     if(!dialog.isConnected)return;
     state.textContent=t('status.FAILED');
     resultBox.textContent=pretty(err);
     errorBox.textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);
   }finally{
     if(dialog.isConnected)button.disabled=false;
   }
 };
 $('#copy-curl').onclick=()=>{try{const body=JSON.stringify(request()).replace(/'/g,"'\\''");copy(`curl -X POST '${location.origin+destination}' \\\n  -H 'Authorization: Bearer YOUR_SCOPED_API_KEY' \\\n  -H 'Content-Type: application/json' \\\n  -H 'Idempotency-Key: ${keyInput.value}' \\\n  --data '${body}'`);}catch{toast(t('invalidJson'));}};
}
async function servicePage(target){const contract=await api('/api/openapi');let pubs=[];if(['ADMIN','DESIGNER'].includes(me.role))pubs=await api('/api/publications');publications=pubs;const services=Object.entries(contract.paths);target.innerHTML=head('servicesTitle','servicesDesc',btn('downloadOpenApi','download-openapi','download'))+`<div class="notice">${tf('serviceUrlNotice')}</div><div class="catalog-grid">${services.map(([path,item])=>`<article class="panel connector-card"><div class="row spread"><span class="badge success">POST</span><span class="badge blue">${tf('published')}</span></div><h3>${e(item.post.summary)}</h3><div class="endpoint">${e(path)}</div><div class="row spread"><button class="button small primary" data-service-run="${e(path)}">${icon('play')}${tf('invoke')}</button><button class="button small" data-copy-path="${e(path)}">${icon('copy')}${tf('copyUrl')}</button>${pubs.some(p=>p.path===path)?`<button class="icon-btn" data-unpublish="${e(pubs.find(p=>p.path===path).id)}" title="${tf('unpublish')}" aria-label="${tf('unpublish')}">${icon('trash')}</button>`:''}</div></article>`).join('')||empty('noPublishedServices')}</div>`;$('#download-openapi').onclick=()=>download(pretty(contract),'connector-hub.openapi.json','application/json');$$('[data-copy-path]').forEach(b=>b.onclick=()=>copy(location.origin+b.dataset.copyPath));$$('[data-service-run]').forEach(b=>b.onclick=()=>{const path=b.dataset.serviceRun,operation=contract.paths[path].post;const schema=operation.requestBody.content['application/json'].schema.properties.input;const parameters=Object.entries(schema.properties).map(([name,s])=>({name,type:s.type==='integer'?'INTEGER':s.type==='number'?'DECIMAL':s.type==='boolean'?'BOOLEAN':s.type==='string'?'STRING':'JSON',source:'INPUT',required:schema.required?.includes(name)}));executionDialog({name:operation.summary,operation:'EXECUTE',parameters},path);});$$('[data-unpublish]').forEach(b=>b.onclick=async()=>{if(!confirm(t('confirmUnpublish')))return;try{await api('/api/publications/'+b.dataset.unpublish,{method:'DELETE'});await renderPage();}catch(err){toast(errorText(err));}});}
async function importOpenApi(){modal(t('importOpenApi'),t('importNotice'),`${selectField('connection','import-connection',connections.filter(c=>['REST','ODATA'].includes(c.type)).map(c=>[c.id,c.name]),'')}${textarea('openApiDocument','import-document','{"openapi":"3.1.1","paths":{}}','jsonOnly',true)}<div id="modal-error" class="error-message" role="alert"></div>`,`<span class="small-text muted">${tf('importDraftsOnly')}</span>${btn('importDrafts','perform-import','download',true)}`,true);$('#perform-import').onclick=async()=>{try{const result=await api('/api/import/openapi',{method:'POST',body:{connectionId:$('#import-connection').value,document:JSON.parse($('#import-document').value)}});closeModal();toast(num(result.length)+' '+t('providersCreated'));await renderPage();}catch(err){$('#modal-error').textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);}};}
async function jobsPage(target){const jobs=await api('/api/jobs');target.innerHTML=head('jobsTitle','jobsDesc',btn('refresh','refresh-jobs','refresh'))+`<div class="notice warning">${tf('unknownWriteNotice')}</div><div class="panel">${jobs.length?`<div class="table-wrap"><table><thead><tr>${['job','provider','status','created','actions'].map(k=>`<th>${tf(k)}</th>`).join('')}</tr></thead><tbody>${jobs.map(j=>`<tr><td class="mono">${e(j.id.slice(0,8))}</td><td>${e(j.name)}</td><td>${badge(j.status)}</td><td>${e(date(j.createdAt))}</td><td><div class="table-actions"><button class="button small" data-job="${e(j.id)}">${tf('details')}</button>${j.status==='QUEUED'?`<button class="button small" data-cancel="${e(j.id)}">${tf('cancel')}</button>`:''}${['FAILED','UNKNOWN'].includes(j.status)&&['ADMIN','DESIGNER'].includes(me.role)?`<button class="button small" data-retry="${e(j.id)}">${tf('retryRead')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('noJobs')}</div>`;$('#refresh-jobs').onclick=()=>renderPage();$$('[data-job]').forEach(b=>b.onclick=async()=>{try{const detail=await api('/api/jobs/'+b.dataset.job);modal(t('jobDetails'),detail.name,`<pre class="result-box">${e(pretty(detail))}</pre>`,'',true);}catch(err){toast(errorText(err));}});for(const [attr,action]of [['cancel','cancel'],['retry','retry']])$$('[data-'+attr+']').forEach(b=>b.onclick=async()=>{try{await api('/api/jobs/'+b.dataset[attr]+'/'+action,{method:'POST',body:{}});await renderPage();}catch(err){toast(errorText(err));}});}
function auditTable(logs,small=false){return `<div class="table-wrap"><table><thead><tr><th>${tf('action')}</th><th>${tf('status')}</th>${small?'':`<th>${tf('principal')}</th>`}<th>${tf('created')}</th>${small?'':`<th>${tf('duration')}</th>`}</tr></thead><tbody>${logs.map(x=>`<tr><td><div class="row-title">${e(t('action.'+x.action)===('action.'+x.action)?x.action:t('action.'+x.action))}</div><div class="sub mono">${e(x.code||x.resource.slice(0,16))}</div></td><td>${badge(x.status)}</td>${small?'':`<td class="mono">${e(x.principal.slice(0,12))}</td>`}<td><span class="small-text">${e(date(x.createdAt))}</span></td>${small?'':`<td class="mono">${num(x.durationMs)} ms</td>`}</tr>`).join('')}</tbody></table></div>`;}
async function auditPage(target){const logs=await api('/api/audit');target.innerHTML=head('auditTitle','auditDesc',btn('exportAudit','export-audit','download'))+`<div class="panel">${logs.length?auditTable(logs):empty('noExecutions')}</div>`;$('#export-audit').onclick=()=>download(pretty(logs),'connector-hub.audit.json','application/json');}
async function keysPage(target){const keys=await api('/api/keys');target.innerHTML=head('keysTitle','keysDesc',btn('createKey','create-key','plus',true))+`<div class="notice">${tf('keyNotice')}</div><div class="panel"><div class="table-wrap"><table><thead><tr>${['name','role','tenant','tokenPrefix','expires','actions'].map(k=>`<th>${tf(k)}</th>`).join('')}</tr></thead><tbody>${keys.map(k=>`<tr><td><strong>${e(k.name)}</strong>${k.revoked?' '+badge('REVOKED'):''}</td><td><span class="badge">${tf('role.'+k.role)}</span></td><td>${e(k.tenant)}</td><td class="mono">${e(k.prefix)}...</td><td>${e(date(k.expiresAt))}</td><td>${k.id!=='bootstrap'&&!k.revoked?`<button class="button small danger" data-revoke="${e(k.id)}">${tf('revoke')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;$('#create-key').onclick=keyEditor;$$('[data-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm(t('confirmRevoke')))return;try{await api('/api/keys/'+b.dataset.revoke,{method:'DELETE'});await renderPage();}catch(err){toast(errorText(err));}});}
async function keyEditor(){providers=await api('/api/providers');modal(t('createKey'),t('keyEditorDesc'),`<div class="fields">${field('name','key-name','API consumer')}${selectField('role','key-role',['INVOKER','AUDITOR','DESIGNER','ADMIN'].map(x=>[x,t('role.'+x)]),'INVOKER')}${field('tenant','key-tenant',me.tenant)}${field('expiresInDays','key-expiry',30,'number')}</div><div class="field"><label for="key-providers">${tf('providerScopes')}</label><select id="key-providers" multiple size="5">${providers.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')}</select></div><div class="check-field"><input type="checkbox" id="key-all"><label for="key-all">${tf('allProvidersExplicit')}</label></div><div id="modal-error" class="error-message" role="alert"></div>`,`<span class="small-text muted">${tf('leastPrivilege')}</span>${btn('createKey','save-key','key',true)}`);$('#save-key').onclick=async()=>{try{const result=await api('/api/keys',{method:'POST',body:{name:$('#key-name').value,tenant:$('#key-tenant').value,role:$('#key-role').value,expiresInDays:Number($('#key-expiry').value),providers:[...$('#key-providers').selectedOptions].map(o=>o.value),allProviders:$('#key-all').checked}});const created=result.token;modal(t('keyCreated'),t('copyOnce'),`<div class="notice warning">${tf('keyCopyWarning')}</div><div class="key-display mono">${e(created)}</div>`,`<span class="small-text muted">${e(result.name)}</span>${btn('copyToken','copy-token','copy',true)}`);$('#copy-token').onclick=()=>copy(created);await renderPage();}catch(err){$('#modal-error').textContent=errorText(err);}};}
async function settingsPage(target){const settings=await api('/api/settings');target.innerHTML=head('settingsTitle','settingsDesc',btn('exportConfig','export-config','download'))+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>${tf('tenantConfiguration')}</h2></div><div class="panel-body">${textarea('configValues','settings-json',pretty(settings),'configValuesHelp',true)}<div id="settings-error" class="error-message" role="alert"></div>${btn('saveSettings','save-settings','check',true)}</div></section><section class="panel"><div class="panel-head"><h2>${tf('operations')}</h2></div><div class="panel-body"><div class="notice">${tf('operatorSettingsNotice')}</div><div class="stack">${btn('inspectUnknown','inspect-unknown','shield')}${btn('pruneHistory','prune-history','trash')}${btn('securityGuide','security-guide','book')}</div><div class="divider"></div><h3>${tf('runtimeBoundaries')}</h3><p class="small-text muted spacer">${tf('runtimeBoundariesDesc')}</p></div></section></div>`;$('#save-settings').onclick=async()=>{try{await api('/api/settings',{method:'PUT',body:JSON.parse($('#settings-json').value)});toast(t('saved'));}catch(err){$('#settings-error').textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);}};$('#export-config').onclick=async()=>{try{download(pretty(await api('/api/export')),'connector-hub.config.json','application/json');}catch(err){toast(errorText(err));}};$('#prune-history').onclick=async()=>{if(!confirm(t('pruneWarning')))return;try{const result=await api('/api/maintenance/prune',{method:'POST',body:{}});toast(num(result.removed)+' '+t('recordsRemoved'));}catch(err){toast(errorText(err));}};$('#security-guide').onclick=()=>{doc='security';navigate('docs');};$('#inspect-unknown').onclick=inspectUnknown;}
async function inspectUnknown(){try{const entries=await api('/api/idempotency');const unknown=entries.filter(x=>x.status==='UNKNOWN');modal(t('unknownExecutions'),t('reconcileWarning'),`<div class="notice warning">${tf('reconcileWarning')}</div><pre class="result-box">${e(pretty(unknown))}</pre><div class="divider"></div>${field('entryId','resolve-id')}${selectField('resolution','resolve-decision',[['CONFIRMED_NO_EFFECT',t('confirmedNoEffect')],['CONFIRMED_SUCCESS',t('confirmedSuccess')]],'CONFIRMED_NO_EFFECT')}${textarea('confirmedResult','resolve-result','{}')}<div id="modal-error" class="error-message" role="alert"></div>`,`<span></span>${btn('recordResolution','resolve-submit','shield',true)}`,true);$('#resolve-submit').onclick=async()=>{if(!confirm(t('reconcileWarning')))return;try{await api('/api/idempotency/'+$('#resolve-id').value+'/resolve',{method:'POST',body:{decision:$('#resolve-decision').value,result:JSON.parse($('#resolve-result').value)}});closeModal();toast(t('saved'));}catch(err){$('#modal-error').textContent=err instanceof SyntaxError?t('invalidJson'):errorText(err);}};}catch(err){toast(errorText(err));}}
const docNames=['user-guide','architecture','api','connectors','security','deployment','testing','operations','provider-parity','commercial-readiness','research'];
async function docsPage(target){target.innerHTML=head('docsTitle','docsDesc')+`<div class="docs-layout"><nav class="doc-nav">${docNames.map(name=>`<button data-doc="${name}" class="${name===doc?'active':''}">${tf('doc.'+name)}</button>`).join('')}</nav><article class="panel"><div class="panel-body"><pre class="docs-text" id="docs-text">${tf('loading')}</pre></div></article></div>`;await loadDoc();$$('[data-doc]').forEach(b=>b.onclick=async()=>{doc=b.dataset.doc;$$('[data-doc]').forEach(x=>x.classList.toggle('active',x===b));await loadDoc();});}
async function loadDoc(){const response=await fetch('/docs/'+lang+'/'+doc+'.md');$('#docs-text').textContent=response.ok?await response.text():t('docsUnavailable');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('copied'));}catch{modal(t('copyManually'),'',`<textarea class="editor">${e(text)}</textarea>`);}}
function download(value,name,type){const blob=new Blob([value],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
await loadLanguage(lang);login();
